import os
import json2

fn main() {
	out := 'tests/android/results/2026-10-23/maps-popup-menus'
	observations := {
		'reviewed_by': 'Root agent drove QMP and reviewed live map, Paris place, route options, Preview and the overflow failure. transition_review independently inspected route-selected.png and route-preview.png, and checked the manual timeline and final fatal serial trace. observer_verify independently validated the frozen input receipt.'
		'map': 'Map-before-input.png was captured after MAP-COLOR-DETECTED at 2026-10-23 18:05:06 UTC+3. Root visually reviewed the live map.'
		'search': 'Clicked search at 18:07:50 UTC+3 and typed Paris at 18:08:01. Search-paris.png at 18:08:10 shows the search before selecting its first suggestion.'
		'place_selection': 'Selected the first Paris suggestion at 18:08:15 UTC+3. Paris-selected.png at 18:08:26 shows the Paris place panel and photos according to root review. Directions was clicked at 18:08:26.'
		'directions': 'Directions-opened.png was captured at 18:08:34 UTC+3. The standard producer typed Versailles, France at 18:08:38; origin-query.png at 18:08:44 shows the full correct query according to root review. Selected the first Versailles / France suggestion at 18:08:49. Route-selected.png at 18:09:06 shows Versailles to Paris, Drive 1 hr 5 min (23 km), transit 13 min, walking 4 hr 25, and Preview / Add stops / Share controls over the area map.'
		'preview': 'Clicked Preview at 18:09:06 UTC+3. Route-preview.png at 18:09:19 shows Route preview, the instruction Head toward Av. de Paris/D186, a detailed street map and previous/next step controls. This verifies Preview display; complete route geometry, estimate accuracy and live navigation remain unverified.'
		'overflow': 'Clicked the Preview overflow control at 18:09:25 UTC+3. The application then exited on missing android.view.ActionProvider. Preview-menu.png capture at 18:09:39 failed because QMP had exited, so this run does not verify the overflow menu display.'
		'fatal': 'Serial lines 148621–148622 record ANDROID-WS-FAIL input or render followed by NoClassDefFoundError: Failed resolution of: Landroid/view/ActionProvider; at bczp.g and Maps AppBar. The ClassNotFoundException cause is at line 148723; APK-SUITE-EXIT code=1 is at line 148725.'
		'raw_outcome': 'startup_failed; APK-SUITE-EXIT id=google-maps code=1 native_observed=true gtk_x11_absent=true. The raw startup classifier is preserved separately from actual map/search/place/route-options/Preview display.'
		'qualification': 'Framework243 changes only framework_classes.v, the new framework_popup_menus.v, and its recorded atlframework/menus.v input relative to Maps242 (112 versus 111 sources). Native236 changes only menus.v from native235, preserving 83 sources. Maps/GMS/Store APKs, launcher and frozen suite239-stream remain identical. Exact source archives, seven pre-run identities and seven staged runtime hashes are retained. The PopupMenu.native_init Preview crash does not recur. Real-app overflow presentation is still blocked by missing ActionProvider; the focused PopupMenu regression is separate evidence. UI remains slow, some icons appear as boxes or circles, and bottom details are clipped. No performance, zoom, location, complete route geometry, estimate-accuracy or live navigation claim is made.'
	}
	os.write_file(out + '/observations.json', json2.encode(observations, prettify: true) + '\n')!
	os.write_file(out + '/README.md', 'Maps243 displays **Route preview**, with the instruction **Head toward Av. de Paris/D186**, a detailed street map and step controls. Live tiles, Paris search and place photos, and Versailles-to-Paris route options also display: Drive **1 hr 5 min (23 km)**, transit **13 min**, walking **4 hr 25**. The full `Versailles, France` query appeared in this run. Clicking Preview\'s overflow control then exits on missing `android.view.ActionProvider`; the menu screenshot failed after exit. Overflow presentation and live navigation remain unverified.\n\nThe previous `PopupMenu.native_init()` Preview crash does not recur. This run uses framework243 (112 exact V sources) with a real Dialog-backed PopupMenu model, and native236 (83 exact sources). Relative to [Maps242](../maps-canvas-save/README.md), the framework changes `framework_classes.v`, the new `framework_popup_menus.v`, and its recorded `atlframework/menus.v` input; native code changes only `menus.v` for Context-based resources, submenu context and ownerless action-view guards. The Maps/GMS/Store APKs, launcher and frozen suite239-stream binary remain identical. The focused PopupMenu regression is separate from this real-app evidence.\n\nSeven pre-run kernel/image/EFI/QEMU/suite hashes and seven staged runtime hashes identify the inputs. Exact V archives, selected generated Smali, build logs, raw application results, complete compressed serial output, screenshots and the manual timeline are retained. The raw classifier remains `startup_failed`, with APK exit code 1 after the overflow click. `observations.json` keeps screenshot interpretation separate from that classifier. The independently verified [native path precision](../interpolators/README.md) and [streaming staging implementation](../maps-window-insets/README.md) remain unchanged.\n\nUI processing remains slow, some icons appear as boxes or circles, and bottom-panel details are clipped. Preview display does not establish complete route geometry, estimate accuracy or live navigation. No performance, zoom or location claim is made.\n\nFrom the repository root, run `/Users/alex/code/v/v_old -nocache -cc cc run tests/android/results/2026-10-23/maps-popup-menus/validate.v result`. Capture `retain.v inputs` while the completed staged module exists, then `retain.v result` after completion; refresh `retain.v manifest` after recording reviewed observations. The validator checks exact source deltas, unchanged binary inputs, staging provenance and the fatal result separately from screenshot interpretation.\n')!
	path := out + '/validate.v'
	mut source := os.read_file(path)!
	old := "\t\tassert observations['preview']!.str().len > 0\n\t\tprintln('MAPS243-INTEGRITY PASS raw results/serial and observations retained; no success inferred from classifier')"
	assert source.count(old) == 1
	source = source.replace(old, "\t\tassert observations['preview']!.str().len > 0\n\t\tassert observations['overflow']!.str().len > 0\n\t\tassert result['outcome']!.str() == 'startup_failed'\n\t\tassert result['process_exited']!.bool() && result['backend_ready']!.bool()\n\t\tassert log.contains('ANDROID-WS-FAIL input or render')\n\t\tassert log.contains('java.lang.NoClassDefFoundError: Failed resolution of: Landroid/view/ActionProvider;')\n\t\tassert log.contains('Caused by: java.lang.ClassNotFoundException: android.view.ActionProvider')\n\t\tassert log.contains('APK-SUITE-EXIT id=google-maps code=1 native_observed=true gtk_x11_absent=true')\n\t\tassert !log.contains('No implementation found for long android.widget.PopupMenu.native_init()')\n\t\tfor name in ['map-before-input', 'search-focused', 'search-paris', 'paris-selected',\n\t\t\t'directions-opened', 'origin-query', 'route-selected', 'route-preview'] {\n\t\t\tbytes := os.read_bytes(out + '/run/' + name + '.png')!\n\t\t\tassert bytes.len > 8 && bytes[..8] == [u8(137), 80, 78, 71, 13, 10, 26, 10], name\n\t\t}\n\t\tassert !os.exists(out + '/run/preview-menu.png')\n\t\ttimeline := os.read_file(out + '/run/manual-timeline.log')!\n\t\tassert timeline.contains('18:09:19 UTC+3 BEGIN') && timeline.contains('/route-preview.png')\n\t\tassert timeline.contains('18:09:25 UTC+3 BEGIN') && timeline.contains(\"'568', '134'\")\n\t\tassert timeline.contains('/preview-menu.png') && timeline.contains('END exit=1 output=No such file or directory')\n\t\tprintln('MAPS243-INTEGRITY PASS Preview image and overflow ActionProvider failure retained; no navigation inferred')")
	os.write_file(path, source)!
}
